fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Closed‐form for S(k) = sum_{i=1..k} a[i], where
    //   a[i] = -i if i odd,
    //   a[i] =  i if i even.
    //
    // One shows:
    //   S(0) = 0,
    //   for k > 0:
    //     if k even: S(k) =  k/2,
    //     if k odd:  S(k) = -(k+1)/2.
    fn prefix_sum(k: i32) -> i32 {
        if k <= 0 {
            0
        } else if k % 2 == 0 {
            k / 2
        } else {
            -((k + 1) / 2)
        }
    }

    let mut out = Vec::with_capacity(queries.len());
    for (l, r) in queries {
        // l >= 1, so (l - 1) >= 0.
        let s_r = prefix_sum(r as i32);
        let s_lm1 = prefix_sum((l as i32) - 1);
        let ans = s_r - s_lm1;
        out.push(ans as i8);
    }
    out
}

